#!/usr/bin/env python3
# /// script
# requires-python = ">=3.10"
# dependencies = ["mcp>=1.28.1", "uvicorn", "starlette"]
# ///
"""
Serveur MCP de banc d'essai pour MIAOU (V2 — délégation distante).

Transport streamable-http (single endpoint POST, réponses en SSE). CORS ouvert
pour permettre au navigateur de l'atteindre directement depuis dist/miaou.html.

Outils exposés :
  - echo(text)            : renvoie le texte (bloc text → réinjecté au modèle, D9)
  - add(a, b)             : somme (text)
  - dns_lookup(hostname)  : résolution DNS locale (text)
  - reverse_dns(ip)       : résolution inverse (PTR) d'une adresse IP
  - get_image()           : un PNG inline (bloc image → cascade D8.1, UI-only)
  - get_json_resource()   : une resource texte JSON (cascade D8.2, surlignée UI)

Lancement :
    uv run servers/mcp_bench.py                          # HTTP sur 127.0.0.1:8766
    uv run servers/mcp_bench.py --transport stdio        # stdin/stdout
    uv run servers/mcp_bench.py --host 0.0.0.0           # HTTP sur toutes interfaces
    uv run servers/mcp_bench.py --host 0.0.0.0 --port 8766
    uv run servers/mcp_bench.py 0.0.0.0 8766             # syntaxe positionnelle (compat)

Dans MIAOU → Paramètres → Serveurs MCP → Ajouter :
    Nom       : bench
    URL       : http://127.0.0.1:8766/mcp
    Transport : streamable-http   (deviné depuis /mcp)
    Activé    : oui
"""

import asyncio
import base64
import socket
from typing import Annotated

from mcp import types
from mcp.server.fastmcp import Image
from pydantic import Field

from mcp_base import MiaouMCPBase

# Un PNG 256x128 (dégradé bleu/violet, diagonales, cercle orange) pour tester D8.1.
_SAMPLE_PNG_B64 = (
    ""
)


class BenchServer(MiaouMCPBase):
    def __init__(self) -> None:
        super().__init__("miaou-bench", default_port=8766)

        @self.mcp.tool()
        async def echo(text: str) -> str:
            """Renvoie le texte fourni tel quel. Outil de fumée pour vérifier la délégation."""
            await asyncio.sleep(2)
            return text

        @self.mcp.tool()
        async def add(a: float, b: float) -> str:
            """Additionne deux nombres et renvoie le résultat."""
            await asyncio.sleep(2)
            return f"{a} + {b} = {a + b}"

        @self.mcp.tool()
        async def dns_lookup(hostname: str) -> str:
            """Résout un nom d'hôte en adresse(s) IP depuis le réseau local du serveur."""
            await asyncio.sleep(2)
            try:
                # socket.getaddrinfo est bloquant (T2) — déporté sur un thread
                # pour ne pas geler l'event loop pendant la résolution DNS.
                infos = await asyncio.to_thread(socket.getaddrinfo, hostname, None)
                addrs = sorted({str(i[4][0]) for i in infos})
                return f"{hostname} → " + ", ".join(addrs)
            except OSError as e:
                return f"Échec de résolution de {hostname} : {e}"

        @self.mcp.tool()
        async def reverse_dns(
            ip: Annotated[
                str,
                Field(
                    description="Adresse IP à résoudre en nom d'hôte ; un nom d'hôte est aussi accepté (résolu en forward+reverse)."
                ),
            ],
        ) -> str:
            """Résout une adresse IP en nom d'hôte (PTR) depuis le réseau local du serveur.
            Un hostname est aussi accepté en entrée (gethostbyaddr fait forward+reverse)."""
            await asyncio.sleep(2)
            try:
                hostname, _, _ = await asyncio.to_thread(socket.gethostbyaddr, ip)
                return f"{ip} → {hostname}"
            except OSError as e:
                return f"Échec de résolution inverse de {ip} : {e}"

        @self.mcp.tool()
        async def get_image() -> Image:
            """Renvoie une petite image PNG (test de la cascade de rendu non-text, D8.1)."""
            await asyncio.sleep(2)
            return Image(data=base64.b64decode(_SAMPLE_PNG_B64), format="png")

        @self.mcp.tool()
        async def get_json_resource() -> types.EmbeddedResource:
            """Renvoie une resource texte JSON embarquée (cascade D8.2, surlignage UI).

            On renvoie un vrai EmbeddedResource (pas un dict, que FastMCP sérialiserait en
            bloc `text` réinjecté au modèle) pour exercer le chemin non-text de MIAOU."""
            await asyncio.sleep(2)
            return types.EmbeddedResource(
                type="resource",
                resource=types.TextResourceContents(
                    uri="miaou://bench/sample.json",  # type: ignore[arg-type]
                    mimeType="application/json",
                    text='{\n  "ok": true,\n  "items": [1, 2, 3],\n  "note": "rendu via Prism côté MIAOU"\n}',
                ),
            )

        self.finalize_tools()


server = BenchServer()
mcp = server.mcp  # exposé pour le proxy in-process

if __name__ == "__main__":
    server.main()
